import heapq
def merge_sorted_list(num1, num2, num3):
    merged = []
    i = j = k = 0
    while i < len(num1) and j < len(num2) and k < len(num3):
        min_val = min(num1[i], num2[j], num3[k])
        merged.append(min_val)
        if min_val == num1[i]:
            i += 1
        elif min_val == num2[j]:
            j += 1
        else:
            k += 1
    # Handle remaining elements in any of the lists
    while i < len(num1):
        merged.append(num1[i])
        i += 1
    while j < len(num2):
        merged.append(num2[j])
        j += 1
    while k < len(num3):
        merged.append(num3[k])
        k += 1
    return merged
```

